 internal static class Patch080Tests
 {
  const BindingFlags P=BindingFlags.Instance|BindingFlags.NonPublic;
  static object Get(object o,string n){return o.GetType().GetField(n,P).GetValue(o);}static void Set(object o,string n,object v){o.GetType().GetField(n,P).SetValue(o,v);}
  static object Call(object o,string n,params object[] a){return o.GetType().GetMethods(P).Single(m=>m.Name==n&&m.GetParameters().Length==a.Length).Invoke(o,a);}
  static void Check(bool b,string m){if(!b)throw new Exception(m);}
  static MapData Data(){return MainWindow.CreateProjectData(15,10,"PointyTop","Próba 0.8.0",PresetCatalog.Default());}
  static IEnumerable<Control> All(Control root){foreach(Control c in root.Controls){yield return c;foreach(var x in All(c))yield return x;}}
  static void Pump(Func<bool> done){Exception failure=null;using(var context=new ApplicationContext())using(var timer=new Timer{Interval=10}){var clock=System.Diagnostics.Stopwatch.StartNew();timer.Tick+=(s,e)=>{try{if(done())context.ExitThread();else if(clock.ElapsedMilliseconds>15000)throw new Exception("Timed out");}catch(Exception ex){failure=ex;context.ExitThread();}};timer.Start();Application.Run(context);}if(failure!=null)throw failure;}
  static void Numbers()
  {
   using(var form=new DarkForm())using(var n=new ScrubNumber{Minimum=1,Maximum=200,Value=5}){form.Controls.Add(n);form.Show();n.Finish(false);int starts=0,ends=0;n.EditStarting+=(s,e)=>starts++;n.EditFinished+=(s,e)=>ends++;
    n.BeginScrub(10);n.MoveScrub(12);Check(n.Value==5&&!n.IsEditing,"Small movement changed number");n.MoveScrub(34);Check((bool)Call(n,"ProcessCmdKey",Message.Create(n.Handle,0x100,IntPtr.Zero,IntPtr.Zero),Keys.Control|Keys.Z),"Scrub routed to map undo");Check(n.Value==8,"8px/unit");n.MoveScrub(18);Check(n.Value==6,"Movement not reversible");n.Finish(true);Check(n.Value==5&&starts==1&&ends==1&&!n.Capture,"Cancel transaction");
    n.BeginScrub(0);n.MoveScrub(2000);n.EndScrub();Check(n.Value==200&&ends==2,"Clamp/commit");n.BeginText();var t=(TextBox)Get(n,"input");t.Text="invalid";Check(!n.CommitText()&&n.Value==200,"Invalid applied");t.Text="1e2";Check(!n.CommitText(),"Unrequested exponent conversion");n.Finish(true);
    var culture=CultureInfo.CurrentCulture;CultureInfo.CurrentCulture=new CultureInfo("pl-PL");try{n.DecimalPlaces=2;n.Increment=.25m;n.Minimum=-2;n.Value=1;n.BeginText();t.Text="1,25";Check(n.CommitText()&&n.Value==1.25m,"Polish fractional input");n.BeginText();t.Text="1,234";Check(!n.CommitText(),"Precision lost silently");n.Finish(true);}finally{CultureInfo.CurrentCulture=culture;}
    n.BeginText();t.Text="bad";Check((bool)Call(n,"ProcessCmdKey",Message.Create(n.Handle,0x100,IntPtr.Zero,IntPtr.Zero),Keys.Tab),"Invalid Tab escaped");n.Finish(true);n.BeginText();t.Text="1,50";CultureInfo.CurrentCulture=new CultureInfo("pl-PL");Check((bool)Call(n,"ProcessCmdKey",Message.Create(n.Handle,0x100,IntPtr.Zero,IntPtr.Zero),Keys.Enter),"Enter routed to parent AcceptButton");CultureInfo.CurrentCulture=culture;Check(n.Value==1.5m&&!n.IsEditing,"Enter commit");n.BeginScrub(0);n.MoveScrub(16);n.Capture=false;Check(n.Value==1.5m&&!n.IsEditing,"Capture loss");n.BeginScrub(0);n.MoveScrub(80);n.Enabled=false;Check(n.Value==1.5m&&!n.Capture,"Disable did not cancel");
   }
   using(var d=new NewMapDialog("PointyTop")){d.Show();var cols=(ScrubNumber)Get(d,"cols");cols.BeginText();((TextBox)Get(cols,"input")).Text="18";Check((bool)Call(cols,"ProcessCmdKey",Message.Create(cols.Handle,0x100,IntPtr.Zero,IntPtr.Zero),Keys.Enter)&&cols.Value==18&&d.DialogResult==DialogResult.None,"Enter accepted NewMap with previous value");Check(All(d).OfType<ScrubNumber>().Count()==2&&d.BackColor.R<80&&All(d).OfType<ComboBox>().All(c=>c.BackColor.R<80),"NewMap theme/numbers");}
   using(var w=new MainWindow(Data(),null)){w.Show();var map=(MapData)Get(w,"map");IconAsset asset;using(var bitmap=new Bitmap(8,8))asset=IconAssets.FromBitmap(bitmap,"Próba");map.IconAssets.Add(asset);var obj=new MapObject{Name="Próba",TemplateId="test",AssetId=asset.Id,X=-1000,Y=-1000};map.Objects.Add(obj);((HashSet<string>)Get(w,"selectedObjects")).Add(obj.Id);Set(w,"rightPanelOpen",true);Call(w,"UpdateUI");Call(w,"CaptureSavedState");var number=(ScrubNumber)Get(w,"objectSize");var stack=(Stack<EditAction>)Get(w,"undo");int before=stack.Count;
    number.BeginScrub(0);number.MoveScrub(16);number.MoveScrub(24);number.EndScrub();Check(stack.Count==before+1&&map.Objects.Single().Size==33,"Scrub must be one document operation");var args=new object[]{false,null};Check((bool)Call(w,"TryHistory",args)&&map.Objects.Single().Size==30,"Scrub undo");args=new object[]{true,null};Check((bool)Call(w,"TryHistory",args)&&map.Objects.Single().Size==33,"Scrub redo");
    number.BeginScrub(0);number.MoveScrub(40);number.Finish(true);Check(stack.Count==before+1&&map.Objects.Single().Size==33,"Cancel left document/history");number.BeginScrub(0);number.MoveScrub(16);number.MoveScrub(0);number.EndScrub();Check(stack.Count==before+1,"No-op left history");var center=BrushGeometry.Center(map,4,4);var live=map.Objects.Single();live.X=center.X;live.Y=center.Y;live.Side="Ally";live.RevealsFog=true;live.RevealRadius=0;foreach(var cell in map.Cells)cell.Fog=true;map.Cells[4+4*map.Columns].Fog=false;Call(w,"CaptureSavedState");Call(w,"UpdateUI");var fogBefore=map.Cells.Select(c=>c.Fog).ToArray();int countBefore=stack.Count;var radius=(ScrubNumber)Get(w,"objectRadius");radius.BeginScrub(0);radius.MoveScrub(16);Check(map.Cells.Count(c=>!c.Fog)>1,"Fog preview fixture did not reveal");radius.Finish(true);Check(map.Cells.Select(c=>c.Fog).SequenceEqual(fogBefore)&&stack.Count==countBefore&&!(bool)Get(w,"dirty"),"Cancel left preview Fog delta");radius.BeginScrub(0);radius.MoveScrub(16);radius.MoveScrub(0);radius.EndScrub();Check(map.Cells.Select(c=>c.Fog).SequenceEqual(fogBefore)&&stack.Count==countBefore,"No-op left preview Fog delta");Call(w,"SelectTool",EditorTool.Stylus);var ink=(ScrubNumber)Get(w,"inkSize");ink.BeginText();((TextBox)Get(ink,"input")).Text="40";var canvas=(Control)Get(w,"canvas");Call(w,"CanvasMouseDown",canvas,new MouseEventArgs(MouseButtons.Left,1,250,200,0));Call(w,"CanvasMouseMove",canvas,new MouseEventArgs(MouseButtons.Left,0,350,200,0));Call(w,"CanvasMouseUp",canvas,new MouseEventArgs(MouseButtons.Left,1,350,200,0));Check(map.Ink.Count==1&&map.Ink[0].Points.Count>1&&(float)Get(w,"inkToolSize")==40,"First stroke after number entry became dot");
   }
   Console.WriteLine("numbers PASS: threshold/click/drag, clamp, cancel/capture/disable, precision/pl-PL, dark NewMap, one document Undo/Redo and no-op rollback");
  }
  static int mainHeight(MainWindow w){return ((MenuStrip)Get(w,"mainMenu")).Height+((ToolStrip)Get(w,"quickStrip")).Height;}
  static void Commands()
  {
   using(var w=new MainWindow(Data(),null)){w.Show();var menu=(MenuStrip)Get(w,"mainMenu");Check(menu.Items.Cast<ToolStripItem>().Select(i=>i.Text.Replace("&","")).SequenceEqual(new[]{"Plik","Edycja","Mapa","Widok","Biblioteka","Pomoc"}),"Categories");var strip=(ToolStrip)Get(w,"quickStrip");Check(strip.Items.OfType<ToolStripControlHost>().Count()==9,"Quick actions lost");Check(((Button)Get(w,"qualityButton")).Text=="High","Initial quality");var canvas=(Control)Get(w,"canvas");var pan=(PointF)Get(w,"pan");float scale=(float)Get(w,"scale");var center=new PointF(canvas.Width/2f,canvas.Height/2f);var world=new PointF((center.X-pan.X)/scale,(center.Y-pan.Y)/scale);int refresh=w.UiRefreshCount;Call(w,"SetZoomPercent",75f);pan=(PointF)Get(w,"pan");Check(Math.Abs((center.X-pan.X)/.75-world.X)<.01&&Math.Abs((center.Y-pan.Y)/.75-world.Y)<.01&&w.UiRefreshCount==refresh,"Zoom center/UpdateUI");
    Call(w,"ShowZoomMenu");var popup=(ContextMenuStrip)Get(w,"zoomPopup");popup.Close(ToolStripDropDownCloseReason.ItemClicked);Check(!popup.IsDisposed,"Popup disposed during click dispatch");((ToolStripMenuItem)popup.Items[3]).PerformClick();Check((float)Get(w,"scale")==1f,"Popup zoom dispatch");var menus=(Dictionary<EditorCommand,ToolStripMenuItem>)Get(w,"commandMenus");Call(w,"ExecuteCommand",EditorCommand.Quality);Check((bool)Get(w,"lowQuality")&&((ToolStripMenuItem)Get(w,"qualityLow")).Checked&&((Button)Get(w,"qualityButton")).ForeColor==ColorTranslator.FromHtml("#4FA7A0"),"Quality sync/accent");Check(!menus[EditorCommand.Rename].Enabled&&!menus[EditorCommand.Undo].Enabled,"Memory rename/undo enabled");Call(w,"AdoptNewProject",Data(),null);Check(w.Text.EndsWith(" *")&&((Button)Get(w,"saveButton")).ForeColor==ColorTranslator.FromHtml("#D77A68")&&!(bool)Get(w,"lowQuality"),"NeedsFirstSave/High/Save accent");
    strip.Width=240;strip.PerformLayout();Check(strip.OverflowButton.Visible&&strip.Items.Cast<ToolStripItem>().Any(i=>i.Placement==ToolStripItemPlacement.Overflow),"No overflow");Check(((Control)Get(w,"shellToolbar")).Controls.Count==2,"Extra toolbar row/name");
    var layers=(ToolStripMenuItem[])Get(w,"layerItems");Check(layers.Length==7&&layers.All(x=>x!=null),"Layer lost");Check(MainWindow.LibraryFolders().Count()==10,"Folder category lost");w.Size=w.MinimumSize;Call(w,"PositionOverlays");Check(((Control)Get(w,"shellToolbar")).Height==mainHeight(w),"Minimum wrapped");w.Scale(new SizeF(1.25f,1.25f));Call(w,"PositionOverlays");Check(menu.Items.Cast<ToolStripItem>().All(i=>i.Bounds.Bottom<=menu.Height)&&strip.Top==menu.Bottom,"125% layout clipping");
    using(var start=new StartWindow((a,b)=>{})){start.Show();var title=All(start).Single(c=>c.Name=="appTitle");var author=All(start).Single(c=>c.Name=="appAuthor");int measured=TextRenderer.MeasureText(title.Text,title.Font,Size.Empty,TextFormatFlags.NoPadding).Width;Check(author.Left>title.Left+measured&&author.Left<title.Right+8,"Author not measured/too wide");}
   }
   Console.WriteLine("commands PASS: categories/actions/layers/folders, quick overflow and exactly two rows, centered zoom without UpdateUI, shared quality/needsFirstSave accents, measured author");
  }
  static void Rename(string root)
  {
   string old=Path.Combine(root,"Mapa źródłowa.hexmap");var data=Data();MainWindow.WriteProjectData(data,old,false);
   using(var w=new MainWindow(MainWindow.ReadProjectData(old),old)){w.Show();string error;Check(w.TryRenameProject("Mapa nowa",out error),error);string next=Path.Combine(root,"Mapa nowa.hexmap");Check(!File.Exists(old)&&File.Exists(next)&&!(bool)Get(w,"dirty")&&RecentProjects.Shared.Entries.Contains(next)&&!RecentProjects.Shared.Entries.Contains(old),"Clean rename/MRU");
    var map=(MapData)Get(w,"map");map.Cells[0].Name="Niezapisany";Call(w,"MarkCellDirty",map.Cells[0]);byte[] original=File.ReadAllBytes(next);Check(w.TryRenameProject("MAPA NOWA.hexmap",out error),error);next=Path.Combine(root,"MAPA NOWA.hexmap");Check((bool)Get(w,"dirty")&&File.ReadAllBytes(next).SequenceEqual(original),"Dirty rename wrote changes");
    string foreign=Path.Combine(root,"Zajęty.hexmap");File.WriteAllText(foreign,"foreign");Check(!w.TryRenameProject("zajęty",out error)&&File.ReadAllText(foreign)=="foreign","Collision overwritten");Check(!w.TryRenameProject("../escape",out error),"Traversal accepted");Set(w,"autoSaving",true);Check(!w.TryRenameProject("Busy",out error),"Rename during auto");Set(w,"autoSaving",false);
    var schedule=(AutoSaveSchedule)Get(w,"autoSchedule");long clock=0;schedule.Clock=()=>clock;schedule.Reset();clock=AutoSaveSchedule.Interval;Call(w,"PollAutoSave");Pump(()=>!(bool)Get(w,"autoSaving"));Check(w.AutoSaveCount==1&&!File.Exists(old)&&MainWindow.ReadProjectData(next).Cells[0].Name=="Niezapisany"&&!(bool)Get(w,"dirty"),"Autosave wrong rename path");
    map.Cells[1].Name="Ręczny";Call(w,"MarkCellDirty",map.Cells[1]);var args=new object[]{next,true,null};Check((bool)Call(w,"TrySaveTo",args)&&MainWindow.ReadProjectData(next).Cells[1].Name=="Ręczny","Manual after rename");File.WriteAllText(next,"foreign-version");Check(!w.TryRenameProject("Obca",out error)&&File.ReadAllText(next)=="foreign-version"&&(string)Get(w,"currentPath")==next,"Foreign/missing rename");File.Delete(next);Check(!w.TryRenameProject("Brak",out error)&&!File.Exists(Path.Combine(root,"Brak.hexmap")),"Missing restored");
   }
   Console.WriteLine("rename PASS: clean/dirty, case-only, MRU, collision/traversal, auto guard, controlled autosave and manual save to new path, external/missing protection; no real5min wait");
  }
  [STAThread]static int Main(string[] args){try{if(args.Length!=1)throw new Exception("One Case required");Application.EnableVisualStyles();Application.SetCompatibleTextRenderingDefault(false);switch(args[0]){case "numbers":Numbers();break;case "commands":Commands();break;case "rename":Rename(AppDomain.CurrentDomain.BaseDirectory);break;default:throw new Exception("Unknown Case");}return 0;}catch(Exception ex){Console.Error.WriteLine(ex);return 1;}}
 }
